const body = $json.body || $json;
const files = Array.isArray(body.files) ? body.files : [];
const message = body.uploadedCount === files.length
  ? `Nightingale upload completed: ${files.join(', ')}`
  : `Nightingale upload completed with a partial result: ${files.join(', ')}`;
return [{ json: { ...body, notification: message, notificationStatus: 'ready' } }];

const body = $json.body || $json;
const files = Array.isArray(body.files) ? body.files : [];
const churnFile = files.find(f => f.toLowerCase().includes('new-churns'));

if (!churnFile) {
  // Nothing to process this run — no new-churns file in this upload
  return [];
}

return [{
  json: {
    fileName: churnFile,
    driveId: 'b!5LI8U-9zuEGR8Mpiv11CX5dfsjMG7vJFqs-9R4iDey-WkeBqAWghT71XbVXo5iHX',
    dropoffPath: "Kim's Tasks/[TESTING] Churns",
    workbookDriveId: 'b!5LI8U-9zuEGR8Mpiv11CX5dfsjMG7vJFqs-9R4iDey-WkeBqAWghT71XbVXo5iHX',
    workbookItemId: '01VGWH2OCKTXDAIMCLTZEKUZLQ3VKVB3YU',
    sheetName: 'Churn',
    tableName: 'ChurnTable'
  }
}];

// NOTE: verify these source field names against the real headers in
// Nightingale's new-churns.csv export, then adjust the right-hand side
// of each line below to match.
const row = $json;
const detectedDate = new Date().toLocaleDateString('en-AU'); // dd/mm/yyyy

return {
  json: {
    DetectedDate: detectedDate,
    'Internal Record #': row['Internal Record #'] || row['InternalRecordNumber'] || row['Record #'] || '',
    FirstName: row['FirstName'] || row['First Name'] || '',
    LastName: row['LastName'] || row['Last Name'] || '',
    IsActive: row['IsActive'] || row['Is Active'] || 'FALSE',
    DateOfBirth: row['DateOfBirth'] || row['Date of Birth'] || row['DOB'] || '',
    ClientTypes: row['ClientTypes'] || row['Client Types'] || '',
    PrimaryPhone: row['PrimaryPhone'] || row['Primary Phone'] || row['Phone'] || '',
    Email: row['Email'] || '',
    Address: row['Address'] || '',
    ServiceExitDate: row['ServiceExitDate'] || row['Service Exit Date'] || '',
    ServiceExitReason: row['ServiceExitReason'] || row['Service Exit Reason'] || row['Reason'] || '',
    Groups: row['Groups'] || ''
  }
};

const columns = [
  'DetectedDate', 'Internal Record #', 'FirstName', 'LastName', 'IsActive',
  'DateOfBirth', 'ClientTypes', 'PrimaryPhone', 'Email', 'Address',
  'ServiceExitDate', 'ServiceExitReason', 'Groups'
];

const values = $input.all().map(item => columns.map(col => item.json[col] ?? ''));

return [{ json: { values } }];

const expectedSheet = $('Prepare Churn Job').first().json.sheetName;
const sheets = ($json.value || []).map(s => s.name);

if (!sheets.includes(expectedSheet)) {
  throw new Error(`Expected worksheet "${expectedSheet}" not found. Found: ${sheets.join(', ')}`);
}

return [{
  json: {
    values: $('Combine Rows For Append').first().json.values,
    tableName: $('Prepare Churn Job').first().json.tableName,
    workbookDriveId: $('Prepare Churn Job').first().json.workbookDriveId,
    workbookItemId: $('Prepare Churn Job').first().json.workbookItemId
  }
}];
